-- Pronunciation clips (eSpeak NG, pre-generated by the vocabula-content audio Action,
-- served by GET /api/audio/:key). The Worker also creates this lazily (worker/schema.ts).
-- Keep it identical to worker/schema.ts (tests/worker.test.ts checks).

CREATE TABLE IF NOT EXISTS audio (
  key TEXT PRIMARY KEY,
  mime TEXT NOT NULL,
  bytes BLOB NOT NULL,
  text TEXT,
  engine TEXT,
  created_at TEXT
);
